function Get-SkillDomain {
    param([string]$Name)
    $lower = $Name.ToLower()
    if ($lower -match '^a-') { return "01-memory-knowledge" }
    if ($lower -match '^(hook|hyperframes|screenshot)') { return "06-frontend-ui" }
    if ($lower -match '^(local-|byted-|pixelle)') { return "03-ai-content" }
    if ($lower -match '^(data-|chart-)') { return "08-data-viz" }
    if ($lower -match '^(frontend|canvas|theme|web-design|gsap)') { return "06-frontend-ui" }
    if ($lower -match '^(agent-browser|browser)') { return "06-frontend-ui" }
    if ($lower -match '^(doc|writing|slides|report)') { return "05-office" }
    if ($lower -match '^(test|debug|refact)') { return "10-gstack" }
    if ($lower -match '^(brainstorm|consult|execut)') { return "04-prompt" }
    if ($lower -in @('天眼一下')) { return "09-dev-tools" }
    if ($lower -match '^_my') { return "02-skill-ecosystem" }
    return "09-dev-tools"
}

// === Domain Classification ===
function getSkillDomain(name) {
    const lower = name.toLowerCase();
    if (lower.startsWith('a-') || lower.startsWith('_my')) return '01-memory-knowledge';
    if (['agent-browser','browser-automation','canvas-design','theme-factory','web-design-guidelines',
         'gsap','frontend-skill','frontend-design','hook-analyzer-skill','screenshot',
         'hyperframes','hyperframes-cli','hyperframes-media','hyperframes-registry'].includes(lower)) return '06-frontend-ui';
    if (['local-asr','local-computer-use','local-img2img','local-mineru','local-ocr-npu',
         'local-realtime-translator','local-screenshot-qa','local-tts','local-txt2img',
         'local-vram','byted-mediakit-shared','byted-seedance-video-generate',
         'byted-seedream-image-generate','pixelle-api-ensure'].includes(lower)) return '03-ai-content';
    if (['data-analysis','data-visualization','chart-visualization',
         'consulting-analysis'].includes(lower)) return '08-data-viz';
    if (['doc-coauthoring','slides','report-generator-skill','writing-plans',
         'executing-plans','brainstorming'].includes(lower)) return '05-office';
    if (['test-driven-development','testing','debugging-fixing','refactoring',
         'gstack'].includes(lower)) return '10-gstack';
    if (['defuddle','deep-research-pro','shell-encoding-pitfalls','utf8-encoding-fix',
         'c-cleanup','skill-install','skill-manager','skills-security-check',
         'github','research-documentation'].includes(lower)) return '09-dev-tools';
    if (lower === '天眼一下') return '09-dev-tools';
    if (lower === 'wechat-automation' || lower === 'ui-ux-pro-max') return '06-frontend-ui';
    if (lower.startsWith('skill_')) return '02-skill-ecosystem';
    return '09-dev-tools';
}

